sys_script_include.script:
var CheckDoseClaim = Class.create();
CheckDoseClaim.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkDose: function() {
        var dose = this.getParameter('sysparm_dose');
        var userId = gs.getUserID();
        var gr = new GlideRecord('x_1216348_claim_0_claim_details');
        gr.addQuery('dose', dose);
        gr.addQuery('emp_num', userId);
        gr.query();

        if (gr.next()) {
            return "CLAIMED|" + gr.getDisplayValue('date');
        } else {
            return "NOT_CLAIMED";
        }
    }
});
